let EvaluationWindow = 30d;
let AvailabilityObjective = 99.9;
let LatencyObjective = 95.0;
let ErrorRateObjective = 1.0;
let LatencyTargetMs = 500.0;
let Results = AppAvailabilityResults
| where TimeGenerated >= ago(EvaluationWindow)
| summarize TotalChecks=count(), SuccessfulChecks=countif(Success == true), FailedChecks=countif(Success == false), FastChecks=countif(Success == true and DurationMs < LatencyTargetMs);
Results
| extend AvailabilityPercent=iff(TotalChecks == 0, real(null), 100.0 * SuccessfulChecks / TotalChecks), LatencyCompliancePercent=iff(SuccessfulChecks == 0, real(null), 100.0 * FastChecks / SuccessfulChecks), SyntheticErrorRatePercent=iff(TotalChecks == 0, real(null), 100.0 * FailedChecks / TotalChecks)
| project Metric=pack_array('Availability', 'Latency compliance', 'Synthetic error rate'), Actual=pack_array(AvailabilityPercent, LatencyCompliancePercent, SyntheticErrorRatePercent), Target=pack_array(AvailabilityObjective, LatencyObjective, ErrorRateObjective), HigherIsBetter=pack_array(true, true, false)
| mv-expand Metric to typeof(string), Actual to typeof(real), Target to typeof(real), HigherIsBetter to typeof(bool)
| extend Status=case(isnull(Actual), 'UNKNOWN', HigherIsBetter and Actual >= Target, 'MET', not(HigherIsBetter) and Actual < Target, 'MET', 'NOT MET')
| project Metric, ActualPercent=round(Actual, 3), TargetPercent=Target, Status
